

import typing

import pydantic
from ...core.pydantic_utilities import IS_PYDANTIC_V2
from .lemur_base_response import LemurBaseResponse
from .lemur_question_answer import LemurQuestionAnswer


class LemurQuestionAnswerResponse(LemurBaseResponse):
    response: typing.List[LemurQuestionAnswer] = pydantic.Field()
    """
    The answers generated by LeMUR and their questions
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
